const GLOBAL_FALLBACK_Z_INDEX_KEY = Symbol.for('Ks.fallbackZIndex');
const DEFAULT_FALLBACK_Z_INDEX = 100000000; // A very large z-index to mock the top-layer behavior
const fallbackZIndexHost = globalThis as Record<PropertyKey, unknown>;

let cachedShowPopoverMethod: (() => void) | null | undefined;
let cachedShowPopoverIsNative = false;
let cachedHidePopoverMethod: (() => void) | null | undefined;
let cachedHidePopoverIsNative = false;

const isNativeShowPopoverMethod = (method?: (() => void) | null) => {
  if (typeof method !== 'function') {
    return false;
  }
  if (method === cachedShowPopoverMethod) {
    return cachedShowPopoverIsNative;
  }

  cachedShowPopoverMethod = method;
  cachedShowPopoverIsNative = /native code/i.test(method.toString());
  return cachedShowPopoverIsNative;
};

const isNativeHidePopoverMethod = (method?: (() => void) | null) => {
  if (typeof method !== 'function') {
    return false;
  }
  if (method === cachedHidePopoverMethod) {
    return cachedHidePopoverIsNative;
  }

  cachedHidePopoverMethod = method;
  cachedHidePopoverIsNative = /native code/i.test(method.toString());
  return cachedHidePopoverIsNative;
};

export const supportsPopoverApi = (element?: Pick<HTMLElement, 'showPopover' | 'hidePopover'> | null) => {
  const showPopover = element?.showPopover;
  const hidePopover = element?.hidePopover;

  if (showPopover || hidePopover) {
    return isNativeShowPopoverMethod(showPopover) && isNativeHidePopoverMethod(hidePopover);
  }

  return (
    typeof HTMLElement !== 'undefined' &&
    isNativeShowPopoverMethod(HTMLElement.prototype.showPopover) &&
    isNativeHidePopoverMethod(HTMLElement.prototype.hidePopover)
  );
};

const parseZIndexFloor = (floor?: string | number) => {
  if (typeof floor === 'number' && Number.isFinite(floor)) {
    return floor;
  }
  if (typeof floor === 'string') {
    const parsed = Number(floor);
    if (!Number.isNaN(parsed) && Number.isFinite(parsed)) {
      return parsed;
    }
  }
  return undefined;
};

const getCurrentFallbackZIndex = () => {
  const current = fallbackZIndexHost[GLOBAL_FALLBACK_Z_INDEX_KEY];
  return typeof current === 'number' ? current : DEFAULT_FALLBACK_Z_INDEX;
};

export const allocateFallbackZIndex = (floor?: string | number) => {
  const next = getCurrentFallbackZIndex() + 1;
  const resolved = Math.max(next, parseZIndexFloor(floor) || DEFAULT_FALLBACK_Z_INDEX);
  fallbackZIndexHost[GLOBAL_FALLBACK_Z_INDEX_KEY] = resolved;

  return typeof floor === 'string' && Number.isNaN(Number(floor)) ? floor : String(resolved);
};
