export const KS_TOP_LAYER_SURFACE_ATTR = 'data-ks-top-layer-surface';

type AttributeTarget = EventTarget & {
  hasAttribute?: (qualifiedName: string) => boolean;
};

const getEventPath = (event: Event): EventTarget[] => event.composedPath?.() ?? (event.target ? [event.target] : []);

export const isTopLayerSurfaceTarget = (target: EventTarget): boolean => {
  const element = target as AttributeTarget;
  return element.hasAttribute?.(KS_TOP_LAYER_SURFACE_ATTR) || false;
};

export const isEventFromTopLayerSurface = (event: Event, boundary?: EventTarget | null): boolean => {
  for (const target of getEventPath(event)) {
    if (boundary && target === boundary) {
      break;
    }

    if (isTopLayerSurfaceTarget(target)) {
      return true;
    }
  }

  return false;
};
